 13→    // Generate root folder AES-256 key (32 random bytes)
 14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
 15→
 16→    // Derive IPNS keypair deterministically via HKDF from user's private key
 17→    let private_key = state
 18→        .private_key
 19→        .read()
 20→        .await
 21→        .as_ref()
 22→        .ok_or("Private key not available for vault IPNS derivation")?
 23→        .clone();
 24→    let private_key_arr: [u8; 32] = private_key
 25→        .as_slice()
 26→        .try_into()
 27→        .map_err(|_| "Invalid private key length")?;
 28→    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
 29→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
 30→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
 31→
 32→    // ECIES-wrap keys with user's uncompressed secp256k1 public key
 33→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
 34→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
 35→    let encrypted_ipns_private_key = crypto::ecies::wrap_key(&ipns_private_key, public_key)
 36→        .map_err(|e| format!("Failed to wrap IPNS private key: {}", e))?;
 37→
 38→    // 1. Register vault with backend
 39→    let init_req = types::InitVaultRequest {
 40→        owner_public_key: hex::encode(public_key),
 41→        encrypted_root_folder_key: hex::encode(&encrypted_root_folder_key),
 42→        encrypted_root_ipns_private_key: hex::encode(&encrypted_ipns_private_key),
 43→        root_ipns_name: root_ipns_name.clone(),
 44→    };
 45→
 46→    let resp = state
 47→        .api
 48→        .authenticated_post("/vault/init", &init_req)
 49→        .await
 50→        .map_err(|e| format!("Vault init request failed: {}", e))?;
 51→
 52→    if !resp.status().is_success() {
 53→        let status = resp.status();
 54→        let body = resp.text().await.unwrap_or_default();
 55→        return Err(format!("Vault init failed ({}): {}", status, body));
 56→    }
 57→
 58→    // 2. Create and publish initial empty folder metadata
 59→    //    Without this, FUSE init() can't resolve the root IPNS name.
 60→    log::info!("Publishing initial empty root folder metadata");
 61→
 62→    let empty_metadata = crypto::folder::FolderMetadata {
 63→        version: "v2".to_string(),
 64→        children: vec![],
 65→    };
 66→
 67→    // Encrypt metadata with root folder key
 68→    let folder_key_arr: [u8; 32] = root_folder_key
 69→        .try_into()
 70→        .map_err(|_| "Invalid root folder key length".to_string())?;
 71→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
 72→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 73→
 74→    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
 75→    let iv_hex = hex::encode(&sealed[..12]);
 76→    use base64::Engine;
 77→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 78→    let json_metadata = serde_json::json!({
 79→        "iv": iv_hex,
 80→        "data": data_base64,
 81→    });
 82→    let json_bytes = serde_json::to_vec(&json_metadata)
 83→        .map_err(|e| format!("JSON serialization failed: {}", e))?;
 84→
 85→    // Upload encrypted metadata to IPFS
 86→    let initial_cid = crate::api::ipfs::upload_content(&state.api, &json_bytes).await?;
 87→
 88→    // Create and sign IPNS record (sequence 0, 24h lifetime)
 89→    let ipns_key_arr: [u8; 32] = ipns_private_key.as_slice()
 90→        .try_into()
 91→        .map_err(|_| "Invalid IPNS private key length".to_string())?;
