 95→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
 96→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
 97→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
