102→        record: record_base64,
103→        metadata_cid: initial_cid,
104→        encrypted_ipns_private_key: None,
105→        key_epoch: None,
106→        expected_sequence_number: None,
107→    };
108→    match crate::api::ipns::publish_ipns(&state.api, &publish_req).await? {
